void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float scale = 2.0*pow( 2.0,-float(iTime));
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = scale*fragCoord/iResolution.xy - scale/2.0;
    uv+=vec2(0.2625, 0.59655);

    vec2 c = uv.xy;
    vec2 z = c;

    float n=0.0;
    float m = 0.0;
    for (;n<300.0 && m<4.0;n++){
        z = vec2( z.x*z.x - z.y*z.y, 2.0*z.x*z.y ) + c; // z = z² + c

        m = dot(z,z);
    }

    float sn = n - log2(log2(m))+4.0;

    vec3 col = 0.5 + 0.5*cos( 3.0 + sn*0.15 + vec3(0.7,0.3,1.0));

    fragColor = vec4(col,1.0);

}
